//! async functions / arrows / methods, await ordering, async generators, for await.

pub const CASES: &[(&str, &str)] = &[
    // basics
    ("var out = []; async function f() { out.push('in'); } f(); out.push('after');", "in,after"),
    ("async function f(a, b) {} [typeof f, f.length, f() instanceof Promise, Object.prototype.toString.call(f())].join()", "function,2,true,[object Promise]"),
    ("async function f() {} new f()", "TypeError!"),
    ("String((async () => 1)())", "[object Promise]"),
    ("var out; async function f() { return 'v'; } f().then(v => { out = v; });", "v"),
    ("var out; async function f() { throw new TypeError('bad'); } f().catch(e => { out = e.name + ':' + e.message; });", "TypeError:bad"),
    ("var out; async function f() { throw 1; } try { f().catch(() => {}); out = 'no sync throw'; } catch (e) { out = 'sync throw'; }", "no sync throw"),
    ("var out; async function f(a = (() => { throw new Error('param'); })()) {} try { f().catch(e => { out = 'rejected ' + e.message; }); } catch (e) { out = 'sync'; }", "rejected param"),
    ("var out; async function f() { const o = { a: await 1, b: [await 2, await 3] }; return o.a + o.b[0] + o.b[1] + (await 4); } f().then(v => { out = v; });", "10"),
    ("var out; (async () => { out = await 1 + await 2; })();", "3"),
    ("var out; (async () => { out = typeof await 1; })();", "number"),
    ("var async = 3; function await_(x) { return x; } var await = 4; async + await", "7"),
    ("function async(x) { return x * 2; } async(4) + async (1)", "10"),
    ("function f() { await 1; }", "SyntaxError!"),
    ("var out; const f = async x => x * 2; const g = async (a, b) => a + b; Promise.all([f(4), g(1, 2)]).then(v => { out = v.join(); });", "8,3"),
    ("var out; const o = { v: 7, m() { return (async () => this.v)(); } }; o.m().then(v => { out = v; });", "7"),
    ("var out; class C { async m() { return await 5; } static async s() { return 's'; } } Promise.all([new C().m(), C.s()]).then(v => { out = v.join(); });", "5,s"),
    ("var out; const o = { async ['m' + 1]() { return 'computed'; }, async *ag() { yield 'x'; } }; o.m1().then(v => o.ag().next().then(r => { out = v + ' ' + r.value; }));", "computed x"),
    ("var out; const fs = []; for (let i = 0; i < 3; i++) fs.push(async () => i * 2); Promise.all(fs.map(f => f())).then(v => { out = v.join(); });", "0,2,4"),
    // await semantics
    ("var out; async function sum(xs) { let t = 0; for (const x of xs) t += await x; return t; } sum([1, Promise.resolve(2), 3]).then(v => { out = v; });", "6"),
    ("var out; async function f() { try { await Promise.reject(new Error('no')); } catch (e) { return 'caught ' + e.message; } } f().then(v => { out = v; });", "caught no"),
    ("var out; async function f() { await Promise.reject('raw'); return 'unreached'; } f().then(v => { out = v; }, e => { out = 'rejected ' + e; });", "rejected raw"),
    ("var out = []; (async () => { try { await Promise.reject(1); } catch (e) { out.push('c' + e); } finally { out.push('f'); } out.push('end'); })();", "c1,f,end"),
    ("var out = []; async function f() { try { await null; return 'r'; } finally { out.push('fin'); } } f().then(v => out.push(v));", "fin,r"),
    ("var out = []; async function f() { for (let i = 0; i < 3; i++) { try { if (i === 1) return 'returned at ' + i; await null; } finally { out.push('fin' + i); } } } f().then(v => out.push(v));", "fin0,fin1,returned at 1"),
    ("var out; async function inner() { await null; throw new RangeError('deep'); } async function outer() { try { await inner(); } catch (e) { return e.name; } } outer().then(v => { out = v; });", "RangeError"),
    ("var out = []; (async () => { const v = await { then(r) { out.push('then called'); r('thenable value'); } }; out.push(v); })(); out.push('sync');", "sync,then called,thenable value"),
    ("var out; async function f() { return { then(r) { r('assimilated'); } }; } f().then(v => { out = v; });", "assimilated"),
    ("var out; async function d(n) { return n === 0 ? 0 : 1 + await d(n - 1); } d(350).then(v => { out = v; });", "350"),
    ("var out; async function f() { function* g() { yield 1; yield 2; } let s = 0; for (const x of g()) s += await x; return s; } f().then(v => { out = v; });", "3"),
    // ordering puzzles
    ("var out = []; async function a1() { out.push('a1 start'); await a2(); out.push('a1 end'); } async function a2() { out.push('a2'); } out.push('script start'); a1(); Promise.resolve().then(() => out.push('p1')).then(() => out.push('p2')); out.push('script end');", "script start,a1 start,a2,script end,a1 end,p1,p2"),
    ("var out = []; (async () => { out.push(1); await null; out.push(3); await null; out.push(5); })(); Promise.resolve().then(() => out.push(4)).then(() => out.push(6)); out.push(2);", "1,2,3,4,5,6"),
    ("var out = []; const p = Promise.resolve(); (async () => { await p; out.push('await 1'); await p; out.push('await 2'); })(); p.then(() => out.push('then 1')).then(() => out.push('then 2'));", "await 1,then 1,await 2,then 2"),
    // an async function returning a promise settles three ticks later than one returning a value
    ("var out = []; async function f() { return Promise.resolve('f'); } f().then(v => out.push(v)); Promise.resolve().then(() => out.push(1)).then(() => out.push(2)).then(() => out.push(3)).then(() => out.push(4));", "1,2,f,3,4"),
    ("var out = []; async function f() { return 'v'; } f().then(v => out.push(v)); Promise.resolve().then(() => out.push(1));", "v,1"),
    ("var out = []; async function w(v, n) { for (let i = 0; i < n; i++) await null; out.push(v); return v; } Promise.all([w('slow', 3), w('fast', 1)]).then(v => out.push(v.join('+')));", "fast,slow,slow+fast"),
    ("var out = []; Promise.reject(new Error('e1')).finally(() => out.push('f1')).finally(() => out.push('f2')).catch(e => out.push(e.message));", "f1,f2,e1"),
    // async generators and for await
    ("var out = []; async function* gen() { yield 1; yield 2; yield 3; } (async () => { for await (const x of gen()) out.push(x); out.push('done'); })();", "1,2,3,done"),
    ("var out = []; (async () => { for await (const x of [Promise.resolve('a'), 'b']) out.push(x); })();", "a,b"),
    ("var out = []; function* g() { yield [1, 'a']; yield [2, 'b']; } (async () => { for await (const [n, s] of g()) out.push(n + s); })();", "1a,2b"),
    ("var out; async function* g() { const a = await Promise.resolve(1); yield a; yield a + 1; return 'ret'; } const it = g(); it.next().then(r1 => it.next().then(r2 => it.next().then(r3 => it.next().then(r4 => { out = [r1, r2, r3, r4].map(r => r.value + ':' + r.done).join(); }))));", "1:false,2:false,ret:true,undefined:true"),
    ("var out; async function* g() { yield 'a'; yield 'b'; } const it = g(); Promise.all([it.next(), it.next(), it.next()]).then(rs => { out = rs.map(r => r.value + ':' + r.done).join(); });", "a:false,b:false,undefined:true"),
    ("var out = []; async function* g() { try { yield 1; yield 2; } finally { out.push('cleanup'); } } const it = g(); it.next().then(() => it.return('early')).then(r => out.push(r.value + ':' + r.done));", "cleanup,early:true"),
    ("var out = []; async function* g() { yield 1; throw new Error('gen failed'); } (async () => { try { for await (const x of g()) out.push(x); } catch (e) { out.push(e.message); } })();", "1,gen failed"),
    ("var out = []; async function* g() { try { yield 1; yield 2; } finally { out.push('closed'); } } (async () => { for await (const x of g()) { out.push(x); break; } out.push('after'); })();", "1,closed,after"),
    ("var out = []; const src = { [Symbol.asyncIterator]() { let i = 0; return { next() { return Promise.resolve({ value: i++, done: i > 3 }); } }; } }; (async () => { for await (const x of src) out.push(x); })();", "0,1,2"),
    ("var out = []; async function* a() { yield 1; yield 2; } async function* b() { yield 0; yield* a(); yield 3; } (async () => { for await (const x of b()) out.push(x); })();", "0,1,2,3"),
    ("var out; async function* g() { yield Promise.resolve('unwrapped'); } g().next().then(r => { out = r.value; });", "unwrapped"),
    ("async function* g() {} const it = g(); [Object.prototype.toString.call(it), it[Symbol.asyncIterator]() === it, it.next() instanceof Promise].join()", "[object AsyncGenerator],true,true"),
    ("var out; async function* g() { const x = yield 1; yield x * 2; } const it = g(); it.next().then(() => it.next(21)).then(r => { out = r.value; });", "42"),
    ("var out; async function* g() { try { yield 1; } catch (e) { yield 'caught ' + e; } } const it = g(); it.next().then(() => it.throw('T')).then(r => { out = r.value; });", "caught T"),
    ("var out; async function* g() { yield 1; } const it = g(); it.return('before start').then(r => it.next().then(r2 => { out = [r.value, r.done, r2.done].join(); }));", "before start,true,true"),
    ("var out = []; async function f() { outer: for await (const x of [1, 2, 3]) { for await (const y of ['a', 'b']) { if (y === 'b') continue outer; out.push(x + y); } } return 'ok'; } f().then(v => out.push(v));", "1a,2a,3a,ok"),
    ("var out; async function f() { for await (const x of [1, 2, 3]) { if (x === 2) return 'found ' + x; } } f().then(v => { out = v; });", "found 2"),
];
